CREATE DATABASE product_db;

USE product_db;

-- 用户表
CREATE TABLE IF NOT EXISTS users (
                       id INT PRIMARY KEY AUTO_INCREMENT COMMENT '用户ID，主键自增',
                       username VARCHAR(50) NOT NULL COMMENT '用户名',
                       email VARCHAR(100) NOT NULL COMMENT '用户邮箱',
                       created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '用户注册时间'
) COMMENT='用户表';

-- 商品表
CREATE TABLE IF NOT EXISTS products (
                          id INT PRIMARY KEY AUTO_INCREMENT COMMENT '商品ID，主键自增',
                          name VARCHAR(100) NOT NULL COMMENT '商品名称',
                          price DECIMAL(10,2) NOT NULL COMMENT '商品单价',
                          stock INT NOT NULL COMMENT '商品库存数量',
                          created_at DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '商品上架时间'
) COMMENT='商品表';

-- 订单表
CREATE TABLE IF NOT EXISTS orders (
                        id INT PRIMARY KEY AUTO_INCREMENT COMMENT '订单ID，主键自增',
                        user_id INT NOT NULL COMMENT '下单用户ID',
                        order_date DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '下单时间',
                        total_amount DECIMAL(10,2) NOT NULL COMMENT '订单总金额',
                        status VARCHAR(20) DEFAULT 'pending' COMMENT '订单状态（pending/completed/cancelled等）',
                        FOREIGN KEY (user_id) REFERENCES users(id)
) COMMENT='订单表';

-- 订单明细表
CREATE TABLE IF NOT EXISTS order_items (
                             id INT PRIMARY KEY AUTO_INCREMENT COMMENT '订单明细ID，主键自增',
                             order_id INT NOT NULL COMMENT '订单ID',
                             product_id INT NOT NULL COMMENT '商品ID',
                             quantity INT NOT NULL COMMENT '购买数量',
                             unit_price DECIMAL(10,2) NOT NULL COMMENT '下单时商品单价',
                             FOREIGN KEY (order_id) REFERENCES orders(id),
                             FOREIGN KEY (product_id) REFERENCES products(id)
) COMMENT='订单明细表';

-- 商品分类表
CREATE TABLE IF NOT EXISTS categories (
                            id INT PRIMARY KEY AUTO_INCREMENT COMMENT '分类ID，主键自增',
                            name VARCHAR(50) NOT NULL COMMENT '分类名称'
) COMMENT='商品分类表';

-- 商品-分类关联表（多对多）
CREATE TABLE IF NOT EXISTS product_categories (
                                    product_id INT NOT NULL COMMENT '商品ID',
                                    category_id INT NOT NULL COMMENT '分类ID',
                                    PRIMARY KEY (product_id, category_id),
                                    FOREIGN KEY (product_id) REFERENCES products(id),
                                    FOREIGN KEY (category_id) REFERENCES categories(id)
) COMMENT='商品与分类关联表';

-- KA商家各平台销售数据表
CREATE TABLE IF NOT EXISTS `dws_seller_sale_day` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `seller_id` bigint DEFAULT NULL COMMENT '商家id',
  `biz_date` date DEFAULT NULL COMMENT '业务日期',
  `platform` varchar(256) DEFAULT NULL COMMENT '平台分类，如：TAOBAO：淘宝&飞猪；DOUYIN：抖音；CTRIP：携程；MEITUAN：美团等',
  `biz_type` varchar(256) DEFAULT NULL COMMENT '业务分类，如：TICKET：门票；VAC_CALENDAR：度假日历；VAC_SUIT：度假套餐；HOTEL_CALENDAR：酒店日历房；HOTEL_SUIT：酒店套餐；CRUISE_CALENDAR：邮轮日历；CRUISE_SUIT：邮轮套餐；OTHER：其他',
  `country` varchar(256) DEFAULT NULL COMMENT '国家，可为空',
  `province` varchar(256) DEFAULT NULL COMMENT '省，可能为空',
  `city` varchar(256) DEFAULT NULL COMMENT '市，可能为空',
  `poi` varchar(256) DEFAULT NULL COMMENT '关联的POI',
  `dim_tag1` varchar(256) DEFAULT NULL COMMENT '自定义维度1，字段具体含义可关联维表dim_tags查询',
  `dim_tag2` varchar(256) DEFAULT NULL COMMENT '自定义维度2，字段具体含义可关联维表dim_tags查询',
  `dim_tag3` varchar(256) DEFAULT NULL COMMENT '自定义维度3，字段具体含义可关联维表dim_tags查询',
  `dim_tag4` varchar(256) DEFAULT NULL COMMENT '自定义维度4，字段具体含义可关联维表dim_tags查询',
  `dim_tag5` varchar(256) DEFAULT NULL COMMENT '自定义维度5，字段具体含义可关联维表dim_tags查询',
  `paid_gmv` decimal(38, 2) DEFAULT NULL COMMENT '卖家付款GMV',
  `receivable_gmv` decimal(38, 2) DEFAULT NULL COMMENT '买家应收GMV',
  `paid_goods_qty` bigint DEFAULT NULL COMMENT '销售份数',
  `paid_nums` bigint DEFAULT NULL COMMENT '销售间夜数或销售份数',
  `refund_gmv` decimal(38, 2) DEFAULT NULL COMMENT '退款金额',
  `book_gmv` decimal(38, 2) DEFAULT NULL COMMENT '预约金额',
  `book_nums` bigint DEFAULT NULL COMMENT '预约间夜数或预约份数',
  `writeoff_gmv` decimal(38, 2) DEFAULT NULL COMMENT '核销金额',
  `writeoff_nums` bigint DEFAULT NULL COMMENT '核销间夜数或核销份数',
  PRIMARY KEY (`id`)
) COMMENT=‘KA商家销售数据表’;

